async function api(path,body){const readRequest=window.carestepHomeReadRequest||((run)=>run());const auth=token,pid=selectedPatient,requestRevision=revision;return readRequest(async signal=>{const r=await fetch('https://carestep-ai-api.kk04sdw.workers.dev'+path,{method:body?'POST':'GET',...(signal?{signal}:{}),cache:'no-store',redirect:'error',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok||d.ok!==true)throw Error(d.error||'조회하지 못했습니다.');return d;},{read:!body,onSlow:()=>{if(auth===token&&requestRevision===revision&&pid===selectedPatient&&path.includes('/'+encodeURIComponent(pid)+'/'))$('homeCareStatus').textContent='연결 확인 중… 일부 조회가 지연되고 있습니다. 다른 영역은 계속 사용할 수 있습니다.';}});}
