function medicationTimeStatus(plan){return {current:'현재 투약·알림 시간 · '+plan.times.join(', '),pending:plan.pendingTimeChange?plan.pendingTimeChange.from+'부터 · '+plan.pendingTimeChange.times.join(', '):'',reason:plan.timeChangeRestricted?'병원에서 시간 변경을 제한했습니다. 변경이 필요하면 병원에 문의해주세요.':plan.timeChangeFrom>plan.endDate?'내일 이후 남은 투약일이 없어 시간을 변경할 수 없습니다.':''};}
