 d.querySelector('.dashboard-head')?.after(section);const picker=section.querySelector('.home-care-picker'),next=section.querySelector('#homeCareNext'),notice=section.querySelector('#homeCareHospitalNotice');const nav=document.createElement('nav');nav.className='home-care-jump';nav.setAttribute('aria-label','건강관리 빠른 이동');for(const [label,id] of [['오늘 관리','homeCareNext'],['건강기록','homeCareHealth'],['병원 자료','r61-home-materials']]){const a=document.createElement('a');a.href='#'+id;a.textContent=label;a.onclick=e=>{const target=$(id);if(!target)return;e.preventDefault();target.setAttribute('tabindex','-1');target.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});target.focus({preventScroll:true});};nav.append(a);}picker.after(nav);nav.after(next);next.after($('homeCarePatients'));$('homeCarePatients').after($('homeCareUpcoming'));$('homeCareUpcoming').after($('homeCareHealth'));$('homeCareHealth').after(notice);arrangeCareUtilities();$('homeGuidePush').onclick=openPushSettings;$('homeGuideDone').onclick=()=>{const id=home?.user?.id;try{if(id)localStorage.setItem('carestep-home-guide:'+id,'done');}catch{}$('homeCareOnboarding').open=false;};$('homeCarePatientSearch').oninput=()=>filterCarePatientCards($('homeCarePatientCards'),$('homeCarePatientSearch').value,selectedPatient);$('homeCareRefresh').onclick=()=>{void refresh();window.carestepRefreshHomePushStatus?.();};$('homeCarePushSettings').onclick=openPushSettings;paintPushStatus();const detail=document.createElement('details');detail.id='homeCareAll';detail.className='home-care-more';const summary=document.createElement('summary');summary.textContent='전체 일정·상담 보기';detail.append(summary);$('homeFollowupSection')?.before(detail);if($('homeFollowupSection'))detail.append($('homeFollowupSection'));for(const x of [d.querySelector('.connection-ready'),$('homePushCard')])if(x)d.append(x);
