function clear(){for(const id of ['homeCarePatients','homeCareHealth']){const n=$(id);if(n?.dataset){delete n.dataset.visibleSignature;delete n.dataset.healthSignature;}}if($('homeCarePatientSearch'))$('homeCarePatientSearch').value='';$('homeMedicationTimeDialog')?.close();$('homeMedicationTimeDialog')?.remove();preventiveChanges.clear();regionReads.clear();revision++;token='';home=null;rows=[];rendered='';selectedPatient='';lastUpdated='';refreshing=false;setCareLoading(false);$('homeCareUpcoming')?.replaceChildren();syncCarePicker();paintFreshness();pushState={kind:'loading'};linkFocused=false;paintPushStatus();clearInterval(timer);timer=null;$('homeCarePatients')?.replaceChildren();$('homeCareRecent')?.replaceChildren();$('homeCareHealth')?.replaceChildren();if($('homeCareNext'))$('homeCareNext').textContent='';if($('homeCareFamilyUpdate'))$('homeCareFamilyUpdate').textContent='';$('homeCareFollowups')?.replaceChildren();$('homeCareHistory')?.close();$('homeCareHistory')?.querySelector('div')?.replaceChildren();if($('homeCareStatus'))$('homeCareStatus').textContent='';}
