function weightChartModel(events,day=today()){
 const valid=(events||[]).filter(e=>e.type==='weight'&&e.status!=='canceled'&&/^\d{4}-\d{2}-\d{2}$/.test(e.eventDate||'')&&e.eventDate<=day&&Number.isFinite(Date.parse(e.eventDate+'T00:00:00Z'))&&new Date(e.eventDate+'T00:00:00Z').toISOString().slice(0,10)===e.eventDate&&e.value!==''&&e.value!==null&&Number.isFinite(Number(e.value))&&Number(e.value)>0).sort((a,b)=>b.eventDate.localeCompare(a.eventDate)||String(b.createdAt||b.updatedAt||'').localeCompare(String(a.createdAt||a.updatedAt||'')));
 const dates=new Map();for(const e of valid)if(!dates.has(e.eventDate))dates.set(e.eventDate,{date:e.eventDate,value:Number(e.value)});const samples=[...dates.values()].slice(0,12).reverse();if(!samples.length)return {samples:[]};const values=samples.map(s=>s.value),min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.2,.1),low=Math.max(0,min-pad),high=max+pad,start=Date.parse(samples[0].date+'T00:00:00Z'),end=Date.parse(samples.at(-1).date+'T00:00:00Z');return {samples,latest:samples.at(-1),low,high,points:samples.map(s=>({...s,x:samples.length===1?198:48+(Date.parse(s.date+'T00:00:00Z')-start)/Math.max(1,end-start)*290,y:20+(high-s.value)/(high-low)*112}))};
}
function weightChartHtml(model){if(!model.samples.length)return '<div class="home-weight-empty">체중 기록을 남기면 여기에서 변화를 확인할 수 있습니다.</div>';const {points,low,high}=model,first=points[0],last=points.at(-1),fmt=n=>String(Number(n.toFixed(2))),axis=[high,(low+high)/2,low];return '<div class="home-weight-chart" tabindex="0" role="region" aria-label="체중 그래프 · 좁은 화면에서는 좌우로 이동할 수 있습니다"><svg viewBox="0 0 360 168" role="img" aria-label="최근 '+points.length+'개 측정일의 체중 변화, 최근 '+last.value+'kg"><title>체중 변화 · '+first.date+' ~ '+last.date+' · 최근 '+last.value+'kg</title>'+axis.map((v,i)=>'<line class="home-weight-grid" x1="48" y1="'+(20+i*56)+'" x2="338" y2="'+(20+i*56)+'"/><text class="home-weight-axis" x="40" y="'+(24+i*56)+'" text-anchor="end">'+fmt(v)+'</text>').join('')+(points.length>1?'<path class="home-weight-area" d="M'+points.map(p=>p.x+','+p.y).join(' L')+' L'+last.x+',132 L'+first.x+',132 Z"/><polyline class="home-weight-line" points="'+points.map(p=>p.x+','+p.y).join(' ')+'"/>':'')+points.map(p=>'<circle class="home-weight-point" cx="'+p.x+'" cy="'+p.y+'" r="4"><title>'+p.date+' · '+p.value+'kg</title></circle>').join('')+'<text class="home-weight-last" x="'+last.x+'" y="'+(last.y-11)+'" text-anchor="'+(points.length===1?'middle':'end')+'">'+last.value+'kg</text><text class="home-weight-axis" x="48" y="158">'+first.date+'</text>'+(points.length>1?'<text class="home-weight-axis" x="338" y="158" text-anchor="end">'+last.date+'</text>':'')+'</svg></div>';
}
function paintHealthSummary(){const host=$('homeCareHealth');if(!host)return;const group=visibleCareRows()[0],healthSignature=JSON.stringify([today(),group?.p.id,group?.p.name,group?.events?.filter(e=>e.type==='weight'),group?.timelineFailed,group?.timelineLoading]);if(host.dataset?.healthSignature===healthSignature){paintRegionFreshness();return;}const wasOpen=host.querySelector?.('.home-weight-values')?.open,focus=document.activeElement,focusText=host.contains?.(focus)?focus.textContent:null;if(host.dataset)host.dataset.healthSignature=healthSignature;host.replaceChildren();if(!group){careLoading(host,home?.connections?.some(c=>c.patients?.length)?'건강기록 확인 중…':'연결된 환자를 확인해주세요.');return;}const heading=document.createElement('h3');heading.textContent=group.p.name+' 건강기록';host.append(heading);if(group.timelineLoading&&!group.events?.length){careLoading(host,'건강기록 확인 중… 복약은 먼저 확인할 수 있습니다.');return;}const model=weightChartModel(group.events),note=document.createElement('p');note.className='home-weight-latest';note.textContent=group.timelineLoading?'건강기록 업데이트 중 · 이전 조회 기록입니다.':group.timelineFailed?(group.timelineLoadedAt?'조회 실패 · 이전 기록 표시 · 마지막 확인 '+stamp(group.timelineLoadedAt):'체중 기록 조회 실패 · 등록 여부를 확인하지 못했습니다.'):model.latest?'최근 체중 '+model.latest.value+'kg · '+model.latest.date:'표시할 체중 기록이 없습니다.';host.append(note);if(!group.timelineFailed&&!group.timelineLoading&&group.timelineLoadedAt){const freshness=document.createElement('p');freshness.className='home-region-freshness';freshness.dataset.regionFreshness='timeline';freshness.hidden=true;freshness.textContent='마지막 확인 · '+stamp(group.timelineLoadedAt);host.append(freshness);}if(group.timelineFailed)careRetry(host,'건강기록만 다시 조회','timeline');if(!group.timelineFailed||model.samples.length){const chart=document.createElement('div');chart.innerHTML=weightChartHtml(model);host.append(chart);if(model.samples.length){const caption=document.createElement('p');caption.className='home-help home-weight-caption';caption.textContent=model.samples.length===1?'현재 체중 기록 1회 · 다음 측정부터 변화 추이를 확인할 수 있습니다.':'최근 '+model.samples.length+'개 측정일 · 같은 날짜는 마지막 측정값 기준 · 단위 kg';const detail=document.createElement('details');detail.className='home-weight-values';detail.innerHTML='<summary>체중 측정값 보기</summary><table><thead><tr><th scope="col">측정일</th><th scope="col">체중 (kg)</th></tr></thead><tbody>'+[...model.samples].reverse().map(p=>'<tr><td>'+p.date+'</td><td>'+p.value+'</td></tr>').join('')+'</tbody></table>';detail.append(caption);detail.open=!!wasOpen;host.append(detail);}}const actions=document.createElement('div');actions.className='home-care-inline-actions';for(const [text,fn,primary] of [['건강기록 전체 보기',()=>window.carestepOpenHomePatientRecord?.(group.p.id),true],['체중 기록 남기기',()=>window.carestepAddHomePatientRecord?.(group.p.id),false]]){const button=document.createElement('button');button.type='button';button.className=primary?'home-primary':'home-secondary';button.textContent=text;button.onclick=fn;actions.append(button);}host.append(actions);if(focusText)[...actions.children].find(n=>n.textContent===focusText)?.focus({preventScroll:true});}
